"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface MemoryStickIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface MemoryStickIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const MemoryStickIcon = forwardRef<MemoryStickIconHandle, MemoryStickIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const pinVariants = (delay: number): Variants => ({
   normal: { scaleY: 1 },
   animate: {
    scaleY: [1, 1.8, 1],
    transition: {
     duration: 0.45 * duration,
     ease: "easeInOut",
     delay: delay * duration,
    },
   },
  });

  const chipVariants = (delay: number): Variants => ({
   normal: { opacity: 1 },
   animate: {
    opacity: [1, 0.2, 1],
    transition: {
     duration: 0.4 * duration,
     ease: "easeInOut",
     delay: delay * duration,
    },
   },
  });

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path d="M12 12v-2" variants={chipVariants(0.14)} />
      <m.path
       d="M12 18v-2"
       variants={pinVariants(0.14)}
       style={{ transformBox: "view-box", originX: "12px", originY: "16px" }}
      />
      <m.path d="M16 12v-2" variants={chipVariants(0.28)} />
      <m.path
       d="M16 18v-2"
       variants={pinVariants(0.21)}
       style={{ transformBox: "view-box", originX: "16px", originY: "16px" }}
      />
      <path d="M2 11h1.5" />
      <m.path
       d="M20 18v-2"
       variants={pinVariants(0.28)}
       style={{ transformBox: "view-box", originX: "20px", originY: "16px" }}
      />
      <path d="M20.5 11H22" />
      <m.path
       d="M4 18v-2"
       variants={pinVariants(0)}
       style={{ transformBox: "view-box", originX: "4px", originY: "16px" }}
      />
      <m.path d="M8 12v-2" variants={chipVariants(0)} />
      <m.path
       d="M8 18v-2"
       variants={pinVariants(0.07)}
       style={{ transformBox: "view-box", originX: "8px", originY: "16px" }}
      />
      <rect x="2" y="6" width="20" height="10" rx="2" />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

MemoryStickIcon.displayName = "MemoryStickIcon";
export { MemoryStickIcon };
